const { exec } = require('child_process');
const args = process.argv.slice(2);

if (args.length === 0) {
  console.log(0);
  process.exit(0);
}

let sum = 0;
for (const arg of args) {
  const num = parseFloat(arg);
  if (isNaN(num)) {
    console.log(1);
    process.exit(1);
  }
  sum += num;
}

console.log(sum);
process.exit(0);
